+      if (bytesRead === 0) break
+      offset += bytesRead
+    }
+    if (offset > MAX_CONFIG_BYTES) {
+      throw new ConfigTooLargeError('Configuration file exceeds the 1 MiB size limit')
+    }
+    return buffer.toString('utf8', 0, offset)
+  } finally {
