+  private async scanForConfigs(repoRoot: string): Promise<RunConfigSource[]> {
+    const ignoreSet = new Set(SAFETY_IGNORE_PATTERNS)
+    const sources: RunConfigSource[] = []
+    await this.walkDir(repoRoot, repoRoot, ignoreSet, sources)
