+  private async walkDir(
+    dir: string,
+    repoRoot: string,
+    ignoreSet: Set<string>,
+    sources: RunConfigSource[],
+  ): Promise<void> {
+    let entries
+    try {
+      entries = await readdir(dir, { withFileTypes: true })
+    } catch {
+      return
+    }
+
+    for (const entry of entries) {
+      if (!entry.isDirectory()) continue
+      if (ignoreSet.has(entry.name)) continue
