+    // provider + baseUrl pair the credentials are keyed by.
+    if (tracker?.baseUrl) {
+      const shared = trackers.some(
+        (t) =>
+          t.id !== trackerId && t.provider === tracker.provider && t.baseUrl === tracker.baseUrl,
+      )
+      if (!shared) {
+        try {
